import{_ as a,o as d,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"التقسيم الموحد لمراتب الزراعة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/14-修炼境界统一划分.md","filePath":"ar/14-修炼境界统一划分.md","lastUpdated":null}'),r={name:"ar/14-修炼境界统一划分.md"};function e(h,t,o,n,p,s){return d(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="التقسيم-الموحد-لمراتب-الزراعة" tabindex="-1">التقسيم الموحد لمراتب الزراعة <a class="header-anchor" href="#التقسيم-الموحد-لمراتب-الزراعة" aria-label="Permalink to &quot;التقسيم الموحد لمراتب الزراعة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>14</td></tr><tr><td>الوحدة</td><td>القوانين الكونية وأنظمة الزراعة</td></tr><tr><td>الكلمات المفتاحية</td><td>تقسيم المراتب، المعيار الموحد، المراتب التسع، المقارنة بين الأنظمة، اعتماد المراسي</td></tr></tbody></table><h2 id="أولاً-ضرورة-التقسيم-الموحد-للمراتب" tabindex="-1">أولاً: ضرورة التقسيم الموحد للمراتب <a class="header-anchor" href="#أولاً-ضرورة-التقسيم-الموحد-للمراتب" aria-label="Permalink to &quot;أولاً: ضرورة التقسيم الموحد للمراتب&quot;">​</a></h2><p>قبل قيام حضارة التكافل المرساة، كانت توجد في هينغ يوانتشو آلاف أنظمة الزراعة، لكل نظام معاييره المستقلة لتقسيم المراتب. أدت هذه المنظومة الفوضوية من المراتب إلى سلسلة من المشكلات: صعوبة مقارنة قوة المزارعين من الأنظمة المختلفة، وغياب لغة مشتركة للتواصل والتعاون بين الأنظمة، وغياب أساس موحد لتوزيع الموارد وتحديد المكانة الاجتماعية، بل ظهور الظلم الجسيم المتمثل في «مرتبة واحدة وقوة مختلفة».</p><p>بعد قيام حضارة التكافل المرساة، لحل هذه المشكلة، وبقيادة «لجنة معايير الزراعة» التابعة لمجلس جمهورية عشرة آلاف عرق، وبمشاركة مزارعين ممثلين عن الأنظمة الثلاثمائة، وبعد بحث وتمحيص طويلين، وُضع هذا «المعيار الموحد لتقسيم مراتب الزراعة». لا يقوم هذا المعيار على أسماء مراتب أي نظام منفرد، بل يتخذ أربعة أبعاد مؤشرات أساسية — عمق فهم المزارع للقوانين الأصلية للكون، ودقة التحكم بالطاقة، ودرجة تطور الوعي، ومدى المساهمة في الشبكة التكافلية — مؤسساً نظاماً موحداً لتقسيم المراتب يعمل عبر الأنظمة.</p><p>المبدأ الأساسي للتقسيم الموحد هو «تقدير الجوهر على الاسم»: أي نظام استخدمه المزارع وأياً كانت أسماء مراتبه، فما دام جوهره بلغ المستوى الموافق في المعيار الموحد، يُعترف به في تلك المرتبة. يضمن هذا المبدأ عدالة وموضوعية تقييم المراتب.</p><h2 id="ثانياً-نظرة-عامة-على-المراتب-التسع" tabindex="-1">ثانياً: نظرة عامة على المراتب التسع <a class="header-anchor" href="#ثانياً-نظرة-عامة-على-المراتب-التسع" aria-label="Permalink to &quot;ثانياً: نظرة عامة على المراتب التسع&quot;">​</a></h2><p>يقسم المعيار الموحد لتقسيم المراتب مسيرة تطور المزارع إلى تسع مراتب كبرى، من الأدنى إلى الأعلى:</p><table tabindex="0"><thead><tr><th>رقم المرتبة</th><th>اسم المرتبة</th><th>الخصائص الأساسية</th><th>المرتبة الموافقة تقريباً في الأصول الثلاثة</th><th>الدور الاجتماعي</th></tr></thead><tbody><tr><td>الأولى</td><td>مرتبة الإحساس بالأصل</td><td>الإدراك المبدئي لوجود الطاقة والقوانين الكونية، وبدء الزراعة المنتظمة</td><td>النظرة الأولى / الإحساس بالحياة / معرفة الفضاء</td><td>مبتدئ</td></tr><tr><td>الثانية</td><td>مرتبة تكثيف الأصل</td><td>امتصاص الطاقة وتكثيفها باستقرار، وبناء الدورة الداخلية الأساسية</td><td>الاستدلال / الدورة / السيطرة على الفضاء</td><td>مزارع مبتدئ</td></tr><tr><td>الثالثة</td><td>مرتبة تحويل الأصل</td><td>تنقية عالية للطاقة، وتحويل الطاقة إلى تطبيقات شتى</td><td>التكرار / التوليد / تحويل الفضاء</td><td>مزارع متوسط</td></tr><tr><td>الرابعة</td><td>مرتبة قانون الأصل</td><td>البدء في فهم القوانين والتحكم بها، واندماج أولي بين الطاقة والقوانين</td><td>الاندماج / التحول الحيوي / قانون الفضاء</td><td>مزارع متقدم</td></tr><tr><td>الخامسة</td><td>مرتبة داو الأصل</td><td>فهم عميق لقوانين مجال معين، وتكوين «داو» شخصي</td><td>الأصل / ولادة الأصل / أصل الفضاء</td><td>مزارع من مرتبة المعلم</td></tr><tr><td>السادسة</td><td>مرتبة الاندماج مع الداو</td><td>اندماج عميق بين الداو الشخصي والقوانين الأصلية للكون، وكل حركة موافقة للداو</td><td>فوق المرتبة الخامسة لنظام واحد</td><td>مزارع من مرتبة الأستاذ الأكبر</td></tr><tr><td>السابعة</td><td>مرتبة اختراق الحدود</td><td>اختراق قيود قوانين الأبعاد، وإجراء عمليات مستقرة بين الأبعاد</td><td>—</td><td>قوي من مرتبة البعد</td></tr><tr><td>الثامنة</td><td>مرتبة خلق العالم</td><td>خلق عوالم كاملة ومنظومات قوانين في فضاء العزل</td><td>—</td><td>قوي من مرتبة العالم</td></tr><tr><td>التاسعة</td><td>مرتبة الأصل</td><td>ملامسة أصل الكون، والمشاركة في الضبط الدقيق لقوانين الكون وتحسينها</td><td>—</td><td>قوي من مرتبة الكون</td></tr></tbody></table><p>من المراتب التسع، الأولى إلى الخامسة هي «مراتب الزراعة البشرية الخمس»، يمكن لمعظم المزارعين بلوغها بالجهد؛ والسادسة إلى التاسعة هي «مراتب الزراعة المقدسة الأربع»، تتطلب موهبة وحظاً وجهداً بالغي السمو، واختراق كل مرتبة حدث عظيم على المستوى الكوني.</p><h2 id="ثالثاً-المعايير-التفصيلية-لكل-مرتبة" tabindex="-1">ثالثاً: المعايير التفصيلية لكل مرتبة <a class="header-anchor" href="#ثالثاً-المعايير-التفصيلية-لكل-مرتبة" aria-label="Permalink to &quot;ثالثاً: المعايير التفصيلية لكل مرتبة&quot;">​</a></h2><h3 id="_3-1-المرتبة-الأولى-الإحساس-بالأصل" tabindex="-1">3.1 المرتبة الأولى: الإحساس بالأصل <a class="header-anchor" href="#_3-1-المرتبة-الأولى-الإحساس-بالأصل" aria-label="Permalink to &quot;3.1 المرتبة الأولى: الإحساس بالأصل&quot;">​</a></h3><p>مرتبة الإحساس بالأصل هي نقطة انطلاق الزراعة، وجوهرها «الإحساس». معايير بلوغها:</p><ul><li>الإحساس المستقر بالطاقة الحرة في الكون (تشي الروحي، قوة القوانين وغيرها)</li><li>امتصاص كميات يسيرة من الطاقة إلى الجسم بالطرق الزراعية الأساسية</li><li>تكوين وعي إدراكي أولي للطاقة، والقدرة على تمييز أنواع الطاقة</li><li>تحسن مبدئي في الصفات الجسدية بسبب تغلغل الطاقة</li></ul><p>مزارعو هذه المرتبة «مبتدئون» في المجتمع، ومهمتهم الرئيسية وضع أساس متين وإيجاد نظام الزراعة المناسب. يستغرق اختراقها عادة أسابيع إلى أشهر من الزراعة المنتظمة.</p><h3 id="_3-2-المرتبة-الثانية-تكثيف-الأصل" tabindex="-1">3.2 المرتبة الثانية: تكثيف الأصل <a class="header-anchor" href="#_3-2-المرتبة-الثانية-تكثيف-الأصل" aria-label="Permalink to &quot;3.2 المرتبة الثانية: تكثيف الأصل&quot;">​</a></h3><p>جوهر هذه المرتبة «التكثيف». معايير بلوغها:</p><ul><li>امتصاص الطاقة الكونية باستقرار وتكثيفها في مخزونات طاقة قابلة للاستخدام داخل الجسم</li><li>بناء منظومة الدورة الداخلية الأساسية، ودوران الطاقة في الجسم عبر مسارات محددة</li><li>استخدام الطاقة المكثفة في تطبيقات هجومية أو دفاعية أو مساندة أساسية</li><li>بلوغ نقاء الطاقة المعيار الأساسي، دون شوائب مفرطة</li></ul><p>يمتلك مزارعو هذه المرتبة هوية المزارع الأساسية، ويمكنهم المشاركة في بعض المهام الزراعية الدنيا والخدمات الاجتماعية. يستغرق الاختراق عادة أشهراً إلى سنوات.</p><h3 id="_3-3-المرتبة-الثالثة-تحويل-الأصل" tabindex="-1">3.3 المرتبة الثالثة: تحويل الأصل <a class="header-anchor" href="#_3-3-المرتبة-الثالثة-تحويل-الأصل" aria-label="Permalink to &quot;3.3 المرتبة الثالثة: تحويل الأصل&quot;">​</a></h3><p>جوهر هذه المرتبة «التحويل». معايير بلوغها:</p><ul><li>تنقية عالية للطاقة، وتحويل نوع من الطاقة إلى نوع آخر</li><li>التفاعل الأولي بين الطاقة والمادة (كلصوق الطاقة بالأشياء وتشكيل الطاقة وغيرها)</li><li>دورة داخلية مستقرة فعالة، وارتفاع كبير في سرعة استشفاف الطاقة</li><li>البدء في الإحساس بوجود القوانين وعملها</li></ul><p>مزارعو هذه المرتبة هم العمود الفقري للمجتمع، ويمكنهم تولي مناصب مرشدين متوسطين وفنيين ومديري قاعدة. يستغرق الاختراق عادة سنوات إلى أكثر من عقد.</p><h3 id="_3-4-المرتبة-الرابعة-قانون-الأصل" tabindex="-1">3.4 المرتبة الرابعة: قانون الأصل <a class="header-anchor" href="#_3-4-المرتبة-الرابعة-قانون-الأصل" aria-label="Permalink to &quot;3.4 المرتبة الرابعة: قانون الأصل&quot;">​</a></h3><p>جوهر هذه المرتبة «القانون». معايير بلوغها:</p><ul><li>فهم القوانين الأساسية لمجال معين والتحكم بها ابتدائياً</li><li>اندماج أولي بين الطاقة والقوانين، مولّداً «قوة القانون» وهي صيغة طاقة أعلى</li><li>إطلاق العويذات والمهارات القائمة على القوانين</li><li>ارتفاع كبير في شدة الوعي، والقدرة على الاستدلال العميق والتأمل الطويل</li></ul><p>مزارعو هذه المرتبة كفاءات متقدمة في المجتمع، ويمكنهم تولي مناصب مرشدين كبار وخبراء تقنيين ومديري وسط. يستغرق الاختراق عادة أكثر من عقد إلى عقود، وهو أول عنق زجاجة كبير في حياة كثير من المزارعين.</p><h3 id="_3-5-المرتبة-الخامسة-داو-الأصل" tabindex="-1">3.5 المرتبة الخامسة: داو الأصل <a class="header-anchor" href="#_3-5-المرتبة-الخامسة-داو-الأصل" aria-label="Permalink to &quot;3.5 المرتبة الخامسة: داو الأصل&quot;">​</a></h3><p>جوهر هذه المرتبة «تكوين الداو». معايير بلوغها:</p><ul><li>فهم منهجي عميق لقوانين مجال معين، وتكوين «داو» شخصي فريد</li><li>رنين الداو الشخصي مع القوانين الكونية، والقدرة على تحريك قوة القوانين في نطاق أوسع</li><li>اندماج عميق بين الطاقة والقوانين، وكل حركة تتضمن قوة القوانين</li><li>تطور الوعي إلى مستوى أعلى، والقدرة على الإدراك الوعائي بين الأبعاد</li></ul><p>مزارعو هذه المرتبة «معلمون» للحضارة، يتمتعون بالسلطة في مجالاتهم، ويمكنهم تولي مناصب مستشارين على مستوى الحضارة ومعلمين كبار ومديرين أعلى. يتطلب الاختراق موهبة وفهمية بالغي السمو؛ وكثيرون لا يبلغونه مدى الحياة.</p><h3 id="_3-6-المرتبة-السادسة-الاندماج-مع-الداو" tabindex="-1">3.6 المرتبة السادسة: الاندماج مع الداو <a class="header-anchor" href="#_3-6-المرتبة-السادسة-الاندماج-مع-الداو" aria-label="Permalink to &quot;3.6 المرتبة السادسة: الاندماج مع الداو&quot;">​</a></h3><p>جوهر هذه المرتبة «الاندماج مع الداو». معايير بلوغها:</p><ul><li>اندماج عميق بين الداو الشخصي والقوانين الأصلية للكون، بلوغ حالة «اتحاد السماء والإنسان»</li><li>إعادة كتابة طريقة عمل القوانين المحلية في نطاق واسع</li><li>بدء تطور شكل الحياة نحو أبعاد أعلى، وتحرر جزئي من قيود الجسد المادي</li><li>إنشاء مجال شخصي مستقر (مجال القوانين)</li></ul><p>مزارعو هذه المرتبة «أساتذة كبار» للحضارة، وشخصيات قمية في مجالات شتى، ولهم تأثير مهم في اتجاه تطور الحضارة. اختراقها حدث كوني يتطلب توافق الزمان والمكان والناس.</p><h3 id="_3-7-المرتبة-السابعة-اختراق-الحدود" tabindex="-1">3.7 المرتبة السابعة: اختراق الحدود <a class="header-anchor" href="#_3-7-المرتبة-السابعة-اختراق-الحدود" aria-label="Permalink to &quot;3.7 المرتبة السابعة: اختراق الحدود&quot;">​</a></h3><p>جوهر هذه المرتبة «اختراق الحدود». معايير بلوغها:</p><ul><li>اختراق قيود قوانين الأبعاد، والتنقل بين الأبعاد دون دعم المراسي</li><li>العمل على غشاء الأبعاد، كفتح ممرات بين الأبعاد وإصلاح شقوقها</li><li>توسع المجال الشخصي إلى فضاء مستقل صغير</li><li>مزيد من ارتفاع أبعاد شكل الحياة، والقدرة على العيش في بيئات قوانين الأبعاد المختلفة</li></ul><p>أصحاب هذه المرتبة كائنات «على مستوى البعد»، قادرون على الاضطلاع المستقل بمهام ومسؤوليات الأبعاد. الاختراق صعب للغاية؛ وعدد من بلغوها في هينغ يوانتشو كله محدود.</p><h3 id="_3-8-المرتبة-الثامنة-خلق-العالم" tabindex="-1">3.8 المرتبة الثامنة: خلق العالم <a class="header-anchor" href="#_3-8-المرتبة-الثامنة-خلق-العالم" aria-label="Permalink to &quot;3.8 المرتبة الثامنة: خلق العالم&quot;">​</a></h3><p>جوهر هذه المرتبة «خلق العالم». معايير بلوغها:</p><ul><li>خلق عوالم كاملة في فضاء العزل، تشمل المادة والطاقة والقوانين والحياة</li><li>تصميم ووضع منظومات القوانين الأساسية للعوالم الجديدة</li><li>توسع المجال الشخصي إلى عالم كامل</li><li>اقتراب شكل الحياة من الوجود عالي الأبعاد، والقدرة على الظهور في عدة أبعاد معاً</li></ul><p>أصحاب هذه المرتبة كائنات «على مستوى العالم»، ويمكن لعوالمهم المخلوقة أن تكون موارد زراعية ومواقع تجارب وملاجئ حضارية. اختراقها من أندر أحداث الكون.</p><h3 id="_3-9-المرتبة-التاسعة-الأصل" tabindex="-1">3.9 المرتبة التاسعة: الأصل <a class="header-anchor" href="#_3-9-المرتبة-التاسعة-الأصل" aria-label="Permalink to &quot;3.9 المرتبة التاسعة: الأصل&quot;">​</a></h3><p>جوهر هذه المرتبة «الأصل». معايير بلوغها:</p><ul><li>ملامسة القوانين الأصلية للكون، والقدرة على فهم قوانينه الغائية في العمل</li><li>المشاركة في الضبط الدقيق لقوانين الكون وتحسينها، والتأثير في اتجاه تطور الكون</li><li>ارتباط عميق بين شكل الحياة وأصل الكون، وكاد يكون خالداً</li><li>القدرة على تحريك قوة الأصل على المستوى الكوني</li></ul><p>أصحاب هذه المرتبة كائنات «على مستوى الكون»، وهم القوة القصوى في هينغ يوانتشو. المزارعون البالغون هذه المرتبة يسمون عادة «قوى الأبعاد العليا»، وهم المجموعة المستهدفة المركزية لـ«استراتيجية التنشيط بنسبة 20%» في الحضارة التكافلية.</p><h2 id="رابعاً-آلية-اعتماد-المراتب" tabindex="-1">رابعاً: آلية اعتماد المراتب <a class="header-anchor" href="#رابعاً-آلية-اعتماد-المراتب" aria-label="Permalink to &quot;رابعاً: آلية اعتماد المراتب&quot;">​</a></h2><p>ضماناً لعدالة ودقة تقييم المراتب، أنشأت الحضارة التكافلية آلية اعتماد صارمة:</p><ol><li><strong>المراقبة الآلية للمراسي</strong>: بعد اتصال المزارع بشبكة المراسي، تراقب المرساة باستمرار مؤشرات مثل مستوى الطاقة وفهم القوانين وشدة الوعي؛ وعند بلوغ المؤشرات معيار مرتبة جديدة تنبه تلقائياً</li><li><strong>تقييم لجنة المعايير</strong>: للاختراقات من المرتبة الرابعة فما فوق، تنظم لجنة معايير الزراعة تقييماً رسمياً يشمل ثلاثة جوانب: الاختبار النظري، واختبار القتال العملي، وتقييم المساهمة</li><li><strong>الإعلان وفترة الاعتراض</strong>: بعد نجاح التقييم، يُعلن عن النتيجة ثلاثين يوماً؛ وخلال هذه الفترة يجوز لأي كائن الاعتراض، وإذا ثبت الاعتراض تُعاد التقييم</li><li><strong>إصدار شهادة المرتبة</strong>: بعد انتهاء فترة الإعلان دون اعتراض، تصدر شبكة المراسي شهادة المرتبة الموحدة، وتُدخل بياناتها في قاعدة بيانات الحضارة</li></ol><h2 id="خامساً-المراتب-والحقوق-والواجبات-الاجتماعية-الموافقة" tabindex="-1">خامساً: المراتب والحقوق والواجبات الاجتماعية الموافقة <a class="header-anchor" href="#خامساً-المراتب-والحقوق-والواجبات-الاجتماعية-الموافقة" aria-label="Permalink to &quot;خامساً: المراتب والحقوق والواجبات الاجتماعية الموافقة&quot;">​</a></h2><p>يتمتع مزارعو المراتب المختلفة بحقوق مختلفة ويتحملون واجبات مختلفة في الحضارة التكافلية:</p><table tabindex="0"><thead><tr><th>المرتبة</th><th>الحقوق الأساسية</th><th>الواجبات الأساسية</th></tr></thead><tbody><tr><td>الإحساس – تكثيف الأصل</td><td>الحصول المجاني على الموارد الزراعية الأساسية، وحق استخدام الأماكن الزراعية العامة</td><td>الالتزام بأخلاقيات الزراعة، والمشاركة في الخدمات المجتمعية الأساسية</td></tr><tr><td>التحويل – قانون الأصل</td><td>حق تخصيص الموارد المتقدمة، وحق التقدم للحصول على صفة المرشد، وحق التنقل بين المناطق</td><td>إرشاد المزارعين المبتدئين، والمشاركة في البحث التقني أو الخدمات الاجتماعية</td></tr><tr><td>داو – الاندماج مع الداو</td><td>حق تخصيص الموارد العالية، وحق الوصول إلى المستويات العليا من المراسي، وحق المشاركة في قرارات الحضارة</td><td>الاضطلاع بمشاريع بحثية على مستوى الحضارة، والحفاظ على استقرار المراسي الإقليمية</td></tr><tr><td>اختراق الحدود – خلق العالم</td><td>حق تخصيص الموارد على مستوى البعد، وحق إنشاء الفضاءات المستقلة، وحق المشاركة في شؤون الأبعاد</td><td>الاضطلاع بمهام مستوى البعد، والحفاظ على استقرار غشاء الأبعاد، والمشاركة في شؤون ما بين الأبعاد</td></tr><tr><td>الأصل</td><td>حق تخصيص الموارد على مستوى الكون، وحق المشاركة في الضبط الدقيق للقوانين، وحق المشاركة في القرارات العليا للحضارة</td><td>الحفاظ على الاستقرار الكلي للكون، وتوجيه اتجاه تطور الحضارة، وتدريب الكفاءات الاحتياطية</td></tr></tbody></table><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>المعيار الموحد لتقسيم مراتب الزراعة أحد البنى الأساسية لمنظومة الزراعة في حضارة التكافل المرساة. يمنح الأنظمة الثلاثمائة «مكيالاً» مشتركاً، ويجعل التواصل والتعاون والتنافس بين الأنظمة ممكناً، ويمنح أساساً موضوعياً لتوزيع الموارد والحكم الاجتماعي وتدريب الكفاءات. تقسيم المراتب التسع ليس لصنع فوارق طبقية، بل لتحديد مرحلة تطور كل مزارع بوضوح، وتقديم أنسب دعم وإرشاد له. الارتقاء في المراتب ليس غاية، بل نقطة انطلاق جديدة نحو تطور تكافلي أعلى.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (نظرة عامة على أنظمة الزراعة الأصلية الثمائة)</li><li>17-位面至高强者标准 (معايير قوى الأبعاد العليا)</li><li>29-共生度评估体系 (منظومة تقييم درجة التكافل)</li></ul>',57)])])}const _=a(r,[["render",e]]);export{b as __pageData,_ as default};
